# ---------------------------------------------------------------------------
# A budget that lies, and why the negatives survive it anyway.
#
# `solve_limited` with a conflict budget came back undecided on queries that
# resolve in three seconds with no budget at all: vertices 184 and 359 of Y
# both exceeded a 60000-conflict budget and then SEPARATED immediately when
# asked without one.  So the budget is not a clean bound -- the solver gives
# up before reaching it -- and any budgeted "undecided" has to be rerun to the
# end before it means anything.
#
# That is the protocol every pair scan here already used: the hard list is
# collected and then rerun without a budget.  And the error points the safe
# way.  Giving up early produces MORE undecideds, never fewer, so
#
#     a scan reporting ZERO hard queries decided every one of them,
#
# and the decided answers -- a model, or a refutation -- are trustworthy
# whatever the budget did.  The negatives stand: G's 21358 pairs at five
# colours, the 81 rotations of K at de Grey's own pair, the 125 second-floor
# unions.  What did not survive is the triage that skipped the rerun.

THE_BUDGET_LIES_BUT_SAFELY = {
    "symptom": "solve_limited came back undecided at a 60000-conflict budget "
               "on queries that resolve in three seconds with no budget",
    "instances": "vertices 184 and 359 of Y, both degree 6, both separating "
                 "immediately once the budget was removed",
    "rule": "every budgeted 'undecided' must be rerun to the end before it "
            "means anything",
    "why_the_negatives_survive": "giving up early produces MORE undecideds, "
                                 "never fewer, so a scan reporting zero hard "
                                 "queries decided every one of them, and a "
                                 "model or a refutation is trustworthy "
                                 "whatever the budget did",
    "unaffected": ["G's 21358 pairs at five colours",
                   "the 81 rotations of K at de Grey's own pair",
                   "the second-floor unions"],
    "affected": "the vertex triage, which skipped the rerun",
}


# ---------------------------------------------------------------------------
# The experiment at five colours that had not actually been run.
#
# The step that works at four is a union whose rotation BITES: Sa and
# rho_4(Sa) share one point and are joined by six edges.  The unions of G
# tried earlier used CLOSING rotations instead -- picked because G realises
# the distance, not because they produce a cross edge -- and they produced
# almost none, +5 on a ring of eleven.  So the analogue at five colours had
# never been performed.
#
# The same equation answers it.  A cross edge is p, q in G with |p - u.q| = 1
# and |u| = 1; with w = u.q, A = |q|^2, P = |p|^2 it forces
#
#     w.pbar = R +- i sqrt(A.P - R^2),     R = (A + P - 1)/2,
#
# so the rotation exists over F(i) exactly when sqrt(A.P - R^2) lies in
# F = Q(sqrt3, sqrt5, sqrt7, sqrt11).  That is a multiquadratic square test,
# and multiquadratic square roots come out of the obvious recursion: with
# y = a + b sqrt(g), a square root u + v sqrt(g) needs a^2 - g b^2 to be a
# square one generator down, and then (a +- that)/2 to be one as well.  The
# b = 0 branch has to try both y and y/g.  Base case Q, everything exact.
#
#     987 rotations of de Grey's field bite G, from 147033 pairs.
#
# Against the 81 that bite Sa over K, and his own single rho_4.

MULTIQUADRATIC_SQUARE_TEST = {
    "recursion": "y = a + b sqrt(g) is a square iff a^2 - g b^2 is one a "
                 "generator down and then (a +- its root)/2 is too",
    "edge_case": "b = 0 needs both y and y/g tried, since y may be g times a "
                 "square",
    "base": "Q, exact throughout -- nothing reconstructed from floats",
}


ROTATIONS_THAT_BITE_G = {
    "why_it_matters": "the four-colour step is a union whose rotation bites; "
                      "the earlier unions of G used closing rotations and got "
                      "+5 cross edges on a ring of eleven, which is not the "
                      "experiment",
    "pairs_tried": 147033,
    "rotations_found": 987,
    "against": "81 that bite Sa over K, and de Grey's own single rho_4",
}


# ---------------------------------------------------------------------------
# Rotations about a pivot, which is the family every solve here had missed.
#
# Every cross-edge solve above looked for u with |p - u.q| = 1, and that is a
# rotation about the ORIGIN.  de Grey's final step is not one: Ya and Yb are Y
# turned about (-2, 0).  So a whole family went untested, and the fix is a
# translation -- a cross edge for the rotation about p0 is
#
#     |p - (p0 + u.(q - p0))| = 1,   i.e.   |p' - u.q'| = 1
#
# for p' = p - p0, q' = q - p0.  The same equation on the translated set, so
# the same machinery, one subtraction earlier.
#
# The difference it makes is not marginal.  Over de Grey's own field, rotations
# about the origin bite G with ONE to FOUR cross edges -- 600 of the 987 solved
# were checked and none did better.  About a vertex of degree 60:
#
#     2371 points, 791 shared,   796 cross edges
#     2813 points, 349 shared,  1182 cross edges
#
# against the six that make his own step work.  Both still 5-colourable, which
# is what a candidate looks like rather than what a failure looks like.
#
# One caution the measurement forced: a rotation that maps the translated set
# to ITSELF is a symmetry, the union adds nothing, and the multiplicity it
# scores is just the edges it preserves.  About the degree-60 vertex exactly
# one of the top forty was such, and it scored the highest count of all --
# 386 against the 199 of the best genuine one.  Symmetries have to go before
# any number means anything.

ROTATE_ABOUT_A_PIVOT_NOT_THE_ORIGIN = {
    "gap": "every cross-edge solve here looked for |p - u.q| = 1, which is a "
           "rotation about the origin; de Grey's final step turns Y about "
           "(-2,0)",
    "fix": "a cross edge about p0 is |p' - u.q'| = 1 for p' = p - p0 and "
           "q' = q - p0 -- the same equation on the translated set",
    "about_the_origin": "rotations of de Grey's field bite G with one to four "
                        "cross edges; 600 of 987 checked, none better",
    "about_a_degree_60_vertex": [
        {"points": 2371, "shared": 791, "cross": 796, "five_colourable": True},
        {"points": 2813, "shared": 349, "cross": 1182, "five_colourable": True},
    ],
    "against": "the six cross edges that make de Grey's own step work",
    "caution": "a rotation mapping the translated set to itself is a symmetry "
               "-- the union adds nothing and the multiplicity it scores is "
               "just the edges it preserves; about the degree-60 vertex one "
               "of the top forty was such and scored the highest count of all",
    "scanned_so_far": "32424 pairs at a closable distance on the 796-cross "
                      "union, none forced",
}


