# Every single-distance lattice graph is bipartite, and that disqualifies the
# whole Erdos direction -- and qualifies the metric that led me into it.
#
# The lattice graphs scored 8.7, 12.7 and 26.4 at FIVE colours where de Grey's
# family scores 1.1, which looked like the five-colour curve rising once the
# degree ceiling was lifted.  They are all 2-chromatic.
#
# It is not an accident of the r chosen.  dx^2 + dy^2 = r gives
# dx + dy = r (mod 2), so:
#
#     r odd          exactly one of dx, dy is odd, so every edge flips the
#                    parity of i + j
#     r = 2 mod 4    dx and dy are both odd, so every edge flips the parity
#                    of i alone
#     r = 0 mod 4    a scaled copy of r/4
#
# In every case a parity is a proper 2-colouring.  The unit-distance graph of
# the integer lattice at a single squared distance is ALWAYS bipartite, and
# four r values with even-parity representations -- 2210, 2900, 2890, 2650, up
# to degree 19.5 and 25281 points -- confirm it: chi = 2 throughout.
#
# So a graph can score twenty-six on the correlation ratio at five colours and
# be incapable of forcing anything whatsoever, having chromatic number two.
# The ratio measures LOCAL correlation, which rises with degree in any graph
# at all; it does not measure proximity to forcing.  Everything in this file
# built on it -- the ladder, the degree curve, the gadget table -- describes
# that weaker quantity, and the two were run together without being separated.
#
# What is not affected is the part that was verified rather than sampled: the
# forced-same and forced-different counts, every candidate put to the solver.
# G's relation at five colours being exactly its edge set is a fact about
# forcing and stands.  Y remains the only graph here with a forced-same pair.
SINGLE_DISTANCE_LATTICES_ARE_BIPARTITE = {
    "proof": "dx^2 + dy^2 = r gives dx + dy = r mod 2.  r odd: one of dx, dy "
             "is odd and every edge flips the parity of i + j.  r = 2 mod 4: "
             "both are odd and every edge flips the parity of i.  r = 0 mod "
             "4: a scaled copy.  A parity is a proper 2-colouring in each "
             "case.",
    "checked": {"25": 2, "65": 2, "325": 2, "1105": 2, "2210": 2, "2900": 2,
                "2890": 2, "2650": 2},
    "up_to": {"degree": 19.54, "points": 25281},
    "what_it_disqualifies": "the Erdos direction entirely -- these graphs "
                            "cannot force anything, having chromatic number "
                            "two",
    "WHAT_IT_QUALIFIES": "the correlation ratio itself.  A 2-chromatic graph "
                         "scores 26.4 at five colours, so the ratio measures "
                         "local correlation, which rises with degree in any "
                         "graph, and NOT proximity to forcing.  The ladder, "
                         "the degree curve and the gadget table all describe "
                         "that weaker quantity.",
    "what_stands": "everything verified rather than sampled.  G's colour "
                   "relation at five colours is exactly its edge set -- all "
                   "6502 candidates put to the solver, every one free -- and "
                   "Y remains the only graph here with a forced-same pair.",
}


# The graded metric, and G is not at chance after all.
#
# Every measurement here asked whether a pair agrees in EVERY sampled
# colouring, which is binary and throws away everything in between.  The
# mechanism of Y says the in-between is the story: Sa alone does not force
# (2,0), (-2,0) -- its 4-colourings split into those that separate the pair
# and those that do not, and six cross edges kill one class.  What matters is
# how big that class was to start with.
#
# Measured as a FREQUENCY, over thirty-two samples, best non-edge pair:
#
#     graph             k    best agreement   chance   times chance
#     Sa                4       27/32 = 0.84     0.25           3.36
#     Sa u rho(Sa)      4       32/32 = 1.00     0.25           4.00
#     Y                 4       32/32 = 1.00     0.25           4.00
#     Sa                5       22/32 = 0.69     0.20           3.45
#     Y                 5       20/32 = 0.62     0.20           3.10
#     G                 5       21/32 = 0.66     0.20           3.30
#
# Sa at four sits at 3.36 times chance and one rotation takes it to 4.00,
# which is the ceiling.  G at five sits at 3.30 -- the same relative position,
# before any rotation.
#
# That corrects the reading, not the data.  The binary metric reported G at
# 1.1 times chance and called it independence, because a pair agreeing 66 per
# cent of the time essentially never agrees thirty-two times running, so it
# vanishes from a count of pairs that always agree.  The graded metric sees
# it, and sees that G has 104 non-edge pairs agreeing in at least seventeen of
# thirty-two, thirty-nine of them at nineteen or more.
#
# What it does NOT say is that a rotation exists to finish the job.  Of G's
# top sixty pairs exactly one sits on a rational closable ring about its own
# midpoint -- the symmetric choice, and de Grey's -- and that ring is D = 1,
# whose rotation lowers the agreement from 18/32 to 12/32.
THE_GRADED_METRIC_PUTS_G_WHERE_SA_WAS = {
    "why_graded": "Sa's colourings split into those separating the pair and "
                  "those not; six edges kill one class.  The size of that "
                  "class is the quantity, and a binary test cannot see it.",
    "best_non_edge_pair_over_32_samples": {
        "Sa at 4": {"agree": 27, "chance": 0.25, "times": 3.36},
        "Sa u rho(Sa) at 4": {"agree": 32, "chance": 0.25, "times": 4.00},
        "Y at 4": {"agree": 32, "chance": 0.25, "times": 4.00},
        "Sa at 5": {"agree": 22, "chance": 0.20, "times": 3.45},
        "Y at 5": {"agree": 20, "chance": 0.20, "times": 3.10},
        "G at 5": {"agree": 21, "chance": 0.20, "times": 3.30},
    },
    "the_correction": "the binary metric reported G at 1.1 times chance and "
                      "read it as independence.  A pair agreeing 66 per cent "
                      "of the time essentially never agrees thirty-two times "
                      "running, so it vanishes from a count of pairs that "
                      "ALWAYS agree.  The data were right; the reading was "
                      "measuring the wrong tail.",
    "G_has": "104 non-edge pairs agreeing in >= 17 of 32, and 39 at >= 19",
    "what_it_does_not_say": "that a rotation exists to finish it.  Of G's top "
                            "sixty pairs exactly one lies on a rational "
                            "closable ring about its own midpoint -- de "
                            "Grey's symmetric choice -- and that ring is "
                            "D = 1, whose rotation takes the agreement DOWN, "
                            "18/32 to 12/32.",
}


# CORRECTION: the maximum agreement over all pairs is an extreme value.
#
# THE_GRADED_METRIC_PUTS_G_WHERE_SA_WAS ranks graphs by their best non-edge
# pair over thirty-two sampled colourings, and a hill-climb was built on it:
# scan unions G u rho(G), take the maximum over every non-edge pair, and watch
# it climb.  It did climb -- 21, then 22, 23, 24, 25 in the first fifty unions
# -- and the climb is free.
#
# The null control is two copies of G translated a thousand apart, so that not
# one edge crosses between them.  Same vertex count, same clause count, same
# search, and exactly zero coupling; whatever the maximum reaches there is
# bought by size alone.  It reaches 23 and 24, against 21 and 22 for G itself.
#
# Two things produce that and neither is the mechanism.  Twice the vertices is
# four times the pairs, and the maximum of four times as many Binomial(32, p)
# draws is higher for free.  And a solver under 5% phase randomisation returns
# less diverse colourings on a bigger instance, which lifts every pair at once.
# The winning union had ONE cross edge and its winning pair lay entirely
