# sqrt(16D - 1) to spindle the antipodal pair it forces.  De Grey's field
# admits twenty-two such D among the rationals with numerator and denominator
# at most forty -- 2/7, 2/5, 4/9, 1/2, 8/7, 4, 17/2 and more.
