# G DOES carry a weak property at five colours -- over five distances, not one.
#
# Single classes were tested and all of them colour; the four carrying classes
# of Sa were tested together and they colour too.  The graded question was
# never asked of G: forbid the closable classes CUMULATIVELY and count how many
# it takes.  Twenty-seven, added smallest first.  Minimised by dropping the
# largest first and keeping every drop that still fails to colour, twenty-seven
# comes down to FIVE, and they are irreducible:
#
#     D = 15/16     1 pair
#     D = 16       12 pairs
#     D = 17/2     24 pairs
#     D = 9        48 pairs
#     D = 7       144 pairs
#                 ---
#                 229 pairs, 2.9% of G's 7877 edges, mean degree 10.0 -> 10.3
#
# So: IN EVERY PROPER 5-COLOURING OF G, AT LEAST ONE OF THOSE 229 PAIRS IS
# MONOCHROMATIC.  That is the first positive statement about G at five colours
# in this work, and it is not a density artefact -- the forbidden set is under
# three per cent of the edges and the mean degree barely moves.
#
# Verified rather than reported: three solvers (cadical, glucose, minisat) all
# return UNSAT on the 229-pair formula; each of the five classes dropped in
# turn lets the graph colour again, so every one is needed; and all 229 pairs
# were re-derived from the exact coordinates, with all five distances closable,
# so the statement is about the plane and not about an indexing slip.
#
# What it is NOT is de Grey's hypothesis.  His is ONE distance and THREE pairs,
# which two rotated copies consume.  Five distances and 229 pairs would need a
# multispindle over five rotation angles and 229 centres, which nothing here
# builds.  The gap between the levels finally has a figure attached: 1 class
# and 3 pairs at four colours, 5 classes and 229 pairs at five.
G_CARRIES_A_WEAK_PROPERTY_AT_FIVE = {
    "statement": "in every proper 5-colouring of G, at least one of 229 "
                 "specific pairs is monochromatic",
    "the classes": {"15/16": 1, "16": 12, "17/2": 24, "9": 48, "7": 144},
    "total pairs": 229,
    "as a fraction of G's edges": 0.029,
    "mean degree": "10.0 -> 10.3, so not a density artefact",
    "cumulative count before minimising": 27,
    "irreducible": "each of the five classes dropped in turn lets G colour "
                   "again",
    "verified by": ["cadical UNSAT", "glucose UNSAT", "minisat UNSAT",
                    "all 229 distances re-derived exactly",
                    "all five distances closable"],
    "what it is not": "de Grey's hypothesis.  His is ONE distance and THREE "
                      "pairs, consumed by two rotated copies.  Five distances "
                      "and 229 pairs need a multispindle over five angles and "
                      "229 centres, which nothing here builds.",
    "the gap, quantified": {"Sa at four": "1 class, 3 pairs",
                            "G at five": "5 classes, 229 pairs"},
}
# REFINEMENT: the neighbourhood lens does discriminate -- between the levels.
#
# NEIGHBOURHOODS_ARE_ALWAYS_BIPARTITE records that every vertex of G and every
# candidate point has its neighbourhood forced to exactly two colours at five,
# and reads that as the forcing being global with no local witness.  True of G
# at five.  Stated generally it is wrong, and the four-colour measurement says
# so:
#
#     Sa at FOUR colours   187 of its 397 vertices forced to 3 of 4
#                          210 forced to 2
#                          the hub, degree 30, forced to 3
#     G  at FIVE colours   all 1581 forced to 2 of 5, the degree-60 hub
#                          included
#
# So at four colours the forcing IS partly local, at 187 sites, and the lens
# was never useless -- it discriminates sharply between the level where the
# mechanism works and the level where it does not:
#
#     Sa at four   3 of 4 available   0.75
#     G  at five   2 of 5 available   0.40
#
# Sa is one colour from rainbow at nearly half its vertices.  G is three
# colours away at every one of them.  That is the difference between the two
# levels, measured, and it is the same difference the class count gives from
# the other side -- one class and three pairs at four, five classes and 229 at
# five.
THE_LENS_DISCRIMINATES_BETWEEN_LEVELS = {
    "Sa at four": {"forced to 3 of 4": 187, "forced to 2": 210,
                   "hub (degree 30)": 3, "ratio": 0.75},
    "G at five": {"forced to 2 of 5": 1581, "hub (degree 60)": 2,
                  "ratio": 0.40},
    "refines": "NEIGHBOURHOODS_ARE_ALWAYS_BIPARTITE, whose reading -- the "
               "forcing is global with no local witness -- holds for G at "
               "five and not in general",
    "the bipartite theorem is untouched": "chi(N(p)) = 2 always; what varies "
                                          "is how many colours the AMBIENT "
                                          "graph forces onto it",
    "so": "Sa is one colour from rainbow at nearly half its vertices, G is "
          "three colours away at all of them",
    "agrees with": "the class count from the other side -- 1 class and 3 "
                   "pairs at four, 5 classes and 229 pairs at five",
}


# The obstruction is small: 63 vertices of G's 1581 carry the whole thing.
#
# G_CARRIES_A_WEAK_PROPERTY_AT_FIVE states it over all 1581 vertices and 229
# pairs, which is true and unwieldy.  Removing vertices only makes colouring
# easier, so any subgraph that still fails is a smaller witness to the same
# fact -- and a small explicit witness is what makes a result checkable by
# someone who did not run the search.
#
#     all of G                1581 vertices   does not colour
#     the pairs' endpoints
#       plus their neighbours  505            does not colour
#     the endpoints alone       71            does not colour
#     peeled to irreducible     63            does not colour, 183 pairs
#
# Sixty-three vertices, and the second peeling sweep drops none, so every one
# of them is load-bearing.
#
# MINIMAL IS NOT MINIMUM, and the orders say so.  Greedy removal stops at a
# set nothing more can leave, but WHICH set depends on the order: dropping by
# descending distance leaves 181 pairs, one random order leaves 159 and
# another 169.  So the pair count is sampled over orders rather than trusted
# from one, and what is reported is an upper bound on the true minimum, not
# the minimum.
#
# The two reductions feed each other -- dropping pairs frees vertices, since a
# vertex matters only through what touches it, and dropping vertices frees
# pairs, since a pair with a removed endpoint goes with it -- so they are run
# alternately rather than once each.
THE_OBSTRUCTION_FITS_IN_SIXTY_THREE_VERTICES = {
    "all of G": {"vertices": 1581, "colours": False},
    "endpoints + neighbours": {"vertices": 505, "colours": False},
    "endpoints alone": {"vertices": 71, "colours": False},
    "peeled": {"vertices": 63, "pairs": 183, "colours": False,
               "second sweep drops": 0},
    "pair counts by removal order": {"descending distance": 181,
                                     "random 1": 159, "random 2": 169},
    "minimal is not minimum": "greedy removal stops where nothing more can "
                              "leave, but which set it stops at depends on "
                              "the order; the figures are upper bounds on the "
                              "minimum",
    "why alternate": "dropping pairs frees vertices and dropping vertices "
                     "frees pairs, so run singly they stop early",
    "and alternating is ALSO order-dependent": "pairs-then-vertices from "
        "71/229 converges to 69 vertices and 166 pairs; vertices-then-pairs "
        "reaches 63 and 161, which is the witness that was kept.  Greedy is "
        "order-dependent at every layer, including the layer that alternates "
        "the layers, so none of these figures is the minimum.",
    "what it gives": "a witness small enough to print -- points with exact "
                     "coordinates, the unit edges among them, and the "
                     "forbidden pairs",
}


# The spindle does not consume a disjunction, confirmed by building it.
#
# The witness says one of 161 pairs is monochromatic in every 5-colouring.
# Turning that into chi >= 6 by argument needs the disjunction consumed, and
# the objection to the two-copy spindle is that a rotated copy is free to have
# a DIFFERENT pair of the list monochromatic, so no contradiction closes.
# That was an objection, not a measurement.
#
# The witness is small enough to settle it by construction.  For each
# forbidden pair (a, b) at squared distance D, take the spindle rotation for D
# about the end a -- checked: it moves the far end by exactly 1 in all five
# classes -- and union the witness with every one of those copies:
#
#     class 15/16     1 copy    125 points     5-colourable
#     class 17/2     10 copies  621            5-colourable
#     class 16       12 copies  771            5-colourable
#     class 9        30 copies 1675            5-colourable
#     class 7       108 copies 2423            5-colourable
#     all five      161 copies 5363 points, 13716 edges, 5-COLOURABLE
#
# So the objection is right and now it is measured: 161 spindle copies of a
# graph whose disjunction is irreducible still colour with five.  On G this
# could not have been tried -- 161 copies of 1581 points is a quarter of a
# million -- and it is the 63-point witness that makes it one SAT call.
SPINDLING_A_DISJUNCTION_DOES_NOT_WORK = {
    "the hypothesis": "one of 161 pairs is monochromatic in every "
                      "5-colouring",
    "the objection": "a rotated copy may have a different pair of the list "
                     "monochromatic, so no contradiction closes",
    "built anyway": {"15/16": {"copies": 1, "points": 125},
                     "17/2": {"copies": 10, "points": 621},
                     "16": {"copies": 12, "points": 771},
                     "9": {"copies": 30, "points": 1675},
                     "7": {"copies": 108, "points": 2423},
                     "all five": {"copies": 161, "points": 5363,
                                  "edges": 13716}},
    "every one": "5-colourable",
    "the rotations are right": "the far end moves by exactly 1 in all five "
                               "classes, checked",
    "why it was affordable": "161 copies of the 63-point witness is 5363 "
                             "points; of G it would have been a quarter of a "
                             "million",
    "so": "the objection is not just an objection -- the construction colours",
}


# The disjunction is exactly "at least one", and that is why the spindle fails.
#
# The witness says some pair of its 161 is monochromatic in every proper
# 5-colouring.  The quantity that matters is not whether but HOW MANY: the
# minimum, over colourings, of how many of the 161 are monochromatic at once.
# A larger minimum is a stronger hypothesis and far easier to consume, since
# "ten of 161" forces ten simultaneous coincidences where "one of 161" leaves
# a rotated copy 160 ways to escape.
#
# Computed exactly, with an indicator per pair tied to the five same-colour
# cases and a cardinality bound:
#
#     at most 0 monochromatic   impossible
#     at most 1 monochromatic   POSSIBLE
#
# So the minimum is one.  There is a proper 5-colouring of the witness with
# exactly one monochromatic pair out of 161, and the hypothesis cannot be
# strengthened at all.
#
# That is the same fact as SPINDLING_A_DISJUNCTION_DOES_NOT_WORK, measured
# from the other side.  The 161 spindle copies colour because each copy needs
# only one coincidence and is free to choose which -- and the minimum being
# one says that freedom is real and not an artefact of how the copies were
# placed.
THE_DISJUNCTION_IS_EXACTLY_ONE = {
    "question": "the minimum over 5-colourings of how many of the 161 pairs "
                "are monochromatic at once",
    "at most 0": "impossible",
    "at most 1": "possible",
    "so the minimum is": 1,
    "method": "one indicator per pair, tied to the five same-colour cases, "
              "with a cardinality bound -- exact, not sampled",
    "why it matters": "a larger minimum would be a stronger hypothesis and "
                      "easier to consume; ten of 161 forces ten simultaneous "
                      "coincidences, one of 161 leaves a rotated copy 160 "
                      "ways to escape",
    "and it explains": "SPINDLING_A_DISJUNCTION_DOES_NOT_WORK -- the 161 "
                       "copies colour because each needs only one "
                       "coincidence and may choose which, and this says that "
                       "freedom is real rather than an artefact of placement",
}


# Minimising the witness destroyed what the bite needs.  The two pull apart.
#
# The spindle fails on the witness for a measured reason, but the spindle is
# stage two of the template and consumes a NAMED pair.  What turns "one of
# three" into "this one" is the BITE, which is a different operation: one copy
# rotated about a common centre by the angle that makes a whole RING touch its
# own image, not one copy per pair about that pair's own end.  It had never
# been applied to the witness.
#
# Applied now -- every vertex and the origin as centre, every rational ring
# the field can bite, both directions -- 177 bites, unions of 183 to 187
# points, about 1100 closable pairs each, and NOT ONE forced pair.
#
# The reason is in the ring sizes: the witness's rings hold two to four
# points.  Sa's D = 4 ring holds six, a full D6 orbit, and the bite hooks all
# six to their images at once; two points hook almost nothing.
#
# And the witness has small rings BECAUSE it was minimised.  Peeling it from
# 1581 vertices to 63 optimised the disjunction -- keep only what is
# load-bearing for "some pair is monochromatic" -- and the ring structure was
# not load-bearing for that, so it went.  The two requirements pull against
# each other: what makes the obstruction small and checkable is exactly what
# makes it unbiteable.
MINIMISING_DESTROYS_THE_RINGS = {
    "the bite": "one copy about a common centre at the angle that makes a "
                "ring touch its image -- the operation that SHARPENS a "
                "disjunction into a named pair",
    "never applied to the witness until now": True,
    "bites tried": 177,
    "union sizes": "183 to 187 points, about 1100 closable pairs each",
    "forced pairs found": 0,
    "why": "the witness's rings hold 2 to 4 points; Sa's D = 4 ring holds "
           "six, a full D6 orbit, and the bite hooks all six at once",
    "and the rings are small because": "the witness was minimised.  Peeling "
                                       "1581 vertices to 63 kept only what "
                                       "is load-bearing for the disjunction, "
                                       "and ring structure is not.",
    "the tension": "what makes the obstruction small and checkable is exactly "
                   "what makes it unbiteable",
}


# Every cap test at five colours had to be run somewhere, and the choice of
# carrier was never examined.  It should have been the first question.
#
# de Grey's H is 4-chromatic and its lemma caps a centre-plus-ring at two
# colours out of four.  Carrier and question carry the same number.  That is
# not a coincidence to note in passing, it is the condition that makes a cap
# possible at all: with k colours available on a graph that only needs k-1,
# one colour is free at every vertex, and a ring can be shown all k by
# permuting inside the slack.  A cap is a statement that the colouring has no
# room, and having no room is what chromaticity means.
#
# Sa and Y are 4-chromatic.  Their universes -- seed plus every unit-circle
# intersection inside the radius -- could have been more, since adding points
# only raises the chromatic number, and if they were, the five-colour cap
# tests run on them were in the right regime after all.  One SAT call per
# carrier settles it, and the answer is that they are not: Sa's universe, 8953
# points and 47724 edges, is 4-colourable.
#
# So every five-colour cap test on an Sa- or Y-seeded universe was asking a
# 4-chromatic graph to have no room for a fifth colour.  The zeros they
# returned are not evidence about caps at five.  They are evidence that the
# carrier was a colour too loose, and they would have come back zero whatever
# the geometry inside them.
#
# G is 5-chromatic, so G-seeded universes are the only ones in this work that
# have ever been in the right regime -- and the 26002-point one is 5-chromatic
# exactly, which is precisely de Grey's situation one level up.
THE_CARRIER_MUST_MATCH_THE_QUESTION = {
    "de Grey's carrier": "H, 4-chromatic; his lemma caps centre+ring at 2 "
                         "colours out of 4",
    "the condition": "a cap says the colouring has no room; a carrier needing "
                     "only k-1 colours has a free colour at every vertex",
    "measured": {
        "Sa universe (8953 points, 47724 edges)": "4-colourable",
        "G universe (26002 points, 122085 edges)": "5-colourable, not 4",
    },
    "consequence": "five-colour cap tests on Sa- and Y-seeded universes were "
                   "a colour too loose; their zeros are not evidence about "
                   "caps at five",
    "the only carriers in the right regime": "G-seeded ones",
    "and this was not checked before": "the cap tests measured the geometry "
                                       "and never measured the carrier",
}


# Symmetrising is de Grey's first move, and it only works at the right centre.
#
# S straddles the origin, so closing it under the order-twelve group there
# makes the twelve images overlap and fuse into one dense graph, Sa.  G does
# not straddle anything near the origin: it is Y turned about the point
# (-2, 0), it occupies the upper half plane around (-2, 2), and closing it
# about the origin gives twelve images standing well apart.  The union has
# 18966 points and 94548 edges -- which is 12 x 7877, G's own edge count,
# exactly, and 9.97 edges per vertex, G's own density, exactly.  Twelve
# disjoint copies of G wearing one name, and 5-colourable for free.
#
# The centre G actually has is the pivot it was built around.  (-2, 0) is a
# vertex of G, 129 of its 1581 points sit at rational distance from it across
# 31 rings, and the twelve images about it are centred two apart on a circle
# of radius two while each has radius about 2.8, so they genuinely overlap.
# Closing G there gives 13873 points from 18972 before overlap, 73782 edges,
# 10.64 per vertex against G's 9.96 -- and every point on a complete ring.
THE_SYMMETRISATION_NEEDS_THE_RIGHT_CENTRE = {
    "about the origin": {"points": 18966, "edges": 94548,
                         "density": "9.97/v, identical to G's own",
                         "what it is": "12 disjoint copies of G"},
    "about the pivot (-2,0)": {"points": 13873, "edges": 73782,
                               "density": "10.64/v",
                               "overlap": "5099 of 18972 points coincide"},
    "how to tell them apart": "edges per vertex; a symmetrisation that does "
                              "not raise it has not overlapped",
    "why the pivot": "it is a vertex of G, and G was built by turning Y "
                     "about it",
    "and Y's centroid is exactly the origin": "Y straddles the origin the "
                                              "way S does; G does not",
}


# Every ring scan in this work filtered to distance squared at most 4, on the
# reflex that a wider ring cannot have two adjacent points on it.  For a
# palette bound that is harmless.  For a BITE it throws away the mechanism.
#
# A bite does not need points of the ring to touch each other.  It needs each
# point to touch its own image under the turn, and 2*rho*sin(theta/2) = 1 has
# a solution at every radius rho >= 1/2.  de Grey's own construction proves
# it: Sb turns Sa by cosine 7/8, the bite on the ring of radius 2, which the
# filter keeps -- but G turns Y by a relative 2*arcsin(1/8), cosine 31/32,
# and that is the bite on the ring of radius FOUR.  Distance squared 16.
# Thrown away by every scan here.
#
# The radius doubles from one level to the next, and the field decides whether
# the next doubling exists: sin theta = sqrt(4*rho^2 - 1)/(2*rho^2), so
# 4*rho^2 - 1 must be a square times one of K's radicands.  rho = 2 gives 15
# and rho = 4 gives 63 = 9*7, which is exactly why de Grey's two angles are
# available at all.  rho = 8 gives 255 = 3*5*17, and 17 is not in K, so the
# obvious third level does not exist over his field -- it would need sqrt17.
#
# But the doubling is not the only way up.  rho = 3 gives 35 and rho = 5 gives
# 99 = 9*11, both in K, and neither has ever been used.
THE_RING_SCAN_THREW_AWAY_DE_GREYS_OWN_BITE = {
    "the filter": "D <= 4 on every ring scan in this work",
    "why it seemed safe": "a ring wider than that has no two adjacent points",
    "why it is not": "a bite stitches each ring point to its own image, not "
                     "to its neighbours, and works at any radius >= 1/2",
    "de Grey's two bites": {"Sa -> Y": "rho = 2, cos 7/8, sin sqrt15/8",
                            "Y -> G": "rho = 4, cos 31/32, sin 3*sqrt7/32"},
    "the radius doubles": "2, then 4",
    "the third doubling does not exist over K": "rho = 8 needs sqrt255 = "
                                                "sqrt(3*5*17), and 17 is not "
                                                "a radicand of K",
    "what K does allow and de Grey never used": {
        "rho = 3": "cos 17/18, sin sqrt35/18",
        "rho = 5": "cos 49/50, sin 3*sqrt11/50",
    },
    "on Gp": "12 biteable rings about the pivot, 11 of them turns nobody "
             "has applied",
}


# The cap is not rare at four colours.  It is everywhere.
#
# Measured on Sa's universe -- Sa plus every unit-circle intersection inside
# radius 4.5, 8953 points -- at de Grey's own strength, a centre together with
# its ring held to two colours out of four: found at the origin on the rings
# D = 16/9 and D = 4, and then again at centres 243, 244, 245, 246 on D = 4/9
# and D = 16/9, one after another.  Thirteen in the first 1600 seconds and
# still arriving.  His configuration is not a needle in a haystack; a scan
# that looks in the right place finds one every couple of minutes.
#
# At five colours, in every carrier whose chromatic number actually matches
# the question, there is not one.  Not a rare one -- none.
THE_CAP_IS_ABUNDANT_AT_FOUR_AND_ABSENT_AT_FIVE = {
    "at four, on Sa's universe": "13+ centre+rings at de Grey's exact depth "
                                 "of 2 out of 4, across 5 distinct centres, "
                                 "on rings D = 4/9 and D = 16/9",
    "at five, on G's universe (35132 points, 5-chromatic)": "579 ball tests "
                                                            "over 40 centres, "
                                                            "0 capped",
    "at five, on Ga (18966 points), whole graph": "0 capped",
    "at five, on Gp (13873 points), whole graph": "0 capped, every ring",
    "the D = 1 ring is capped for free": "the centre touches all of it, so "
                                         "the ring loses the centre's colour "
                                         "and the bound is k-1 with no "
                                         "geometry involved; centre+ring is k",
    "so the gap is not one of degree": "abundant at four, absent at five",
}


# de Grey's first step, derived from nothing but a scan.
#
# Taking Sa -- 397 points, 4-chromatic, his symmetric seed closure -- and
# asking, for every vertex as a centre and every same-distance class about it,
# how many colours the class can show and how many the class and its centre
# can show between them, on the whole graph and with no radius filter:
#
#   centre 0, D = 4, six points, palette 2, centre+ring 2
#
# That is his lemma, at full strength, with the number he uses: a centre
# together with its radius-2 hexagon takes at most TWO colours out of four.
# The six points are the order-twelve orbit of (2, 0).  And the bite that ring
# admits is cos 7/8, sin sqrt15/8 -- which is Sb, the rotation by 2*arcsin(1/4)
# that turns Sa into Y.  The cap and the bite are the same ring seen twice.
#
# The proof is not cheap even at this size: the five other rings about the
# origin answer in tenths of a second because they are satisfiable, and the
# capped one takes 154 seconds of unsatisfiability on 397 points.  Which is
# also the reason a negative from these scans is sound rather than a timeout:
# the scans return quickly precisely when a colouring showing all k colours
# exists, and slowly only when none does.
#
# The same scan on G at five colours -- all 1581 centres, every radius, whole
# graph -- returns nothing at all.  Not a shallow cap, not one ring.
SA_IS_CAPPED_AT_ITS_OWN_BITE_RADIUS = {
    "Sa at four colours": {"centre": 0, "D": "4 (radius 2)", "points": 6,
                           "ring palette": 2, "centre+ring palette": 2,
                           "which is": "de Grey's lemma, at his own number"},
    "the bite that ring admits": "cos 7/8, sin sqrt15/8 -- exactly Sb",
    "so cap and bite are one ring": "the hexagon that is held to two colours "
                                    "is the hexagon the rotation stitches",
    "cost of the proof": "154s unsatisfiable on 397 points; the five "
                         "uncapped rings about the same centre answer in "
                         "tenths of a second",
    "why that makes the negatives sound": "these scans are fast exactly when "
                                          "a colouring exists, so a quick "
                                          "'uncapped' is an answer, not a "
                                          "timeout",
    "G at five colours, same scan": "1581 centres, every radius, whole graph, "
                                    "0 capped rings at any depth",
}


# The third level of de Grey's recursion, and the two separate walls it hits.
#
# His rule, read off the construction: bite a ring of radius rho about c, move
# the centre to a point of that ring, bite a ring of radius 2*rho about it.
# Level one is radius 2 and cosine 7/8; level two is radius 4 about (-2, 0)
# and cosine 31/32.  Level three asks for radius 8 and cosine 127/128, whose
# sine is sqrt(255)/128 = sqrt(3*5*17)/128.
#
# The first wall is the field: 17 is not a radicand of Q(sqrt3, sqrt5, sqrt7,
# sqrt11), so the turn does not exist there.  That one is an instruction
# rather than an obstacle -- adjoining sqrt17 makes it exact, the field has
# dimension 32, and G rebuilds over it unchanged at 1581 points.
#
# The second wall does not move.  Over the extended field the radius-4 ring
# about the pivot -- the one level two bites -- holds exactly TWO points of G,
# and no point of G lies at distance 8 from either of them.  G reaches only
# about 4.8 from the pivot, and a centre 4 out from there puts everything
# within 8.8 but nothing at 8.  There is no radius-8 ring to bite.
#
# So the recursion stops on geometry as well as on arithmetic.  Each level
# needs a carrier twice as wide as the last, and unions of rotations about a
# fixed centre do not widen anything -- they fill in, they do not reach out.
# That is a requirement on the carrier that no operation in the catalogue
# supplies.
THE_THIRD_LEVEL_NEEDS_A_WIDER_GRAPH_NOT_JUST_A_BIGGER_FIELD = {
    "the rule": "bite radius rho about c; move to a point of that ring; bite "
                "radius 2*rho about it",
    "level 1": "radius 2, cos 7/8, sin sqrt15/8 -- Sb",
    "level 2": "radius 4 about (-2,0), cos 31/32, sin 3*sqrt7/32 -- G",
    "level 3 would be": "radius 8, cos 127/128, sin sqrt(3*5*17)/128",
    "wall one, the field": "17 is not a radicand of K; adjoining sqrt17 "
                           "removes this, dimension 32, G unchanged",
    "wall two, the width": "the radius-4 ring about the pivot holds 2 points "
                           "of G, and no point of G is 8 from either; G "
                           "reaches 4.8 from the pivot",
    "what it means": "each level needs a carrier twice as wide, and unions of "
                     "rotations about a fixed centre fill in rather than "
                     "reach out",
    "so the missing operation is not a turn": "it is whatever makes the "
                                              "carrier wider while keeping it "
                                              "chromatically tight",
}


# Why symmetrising a graph usually does nothing, stated exactly.
#
# Three closures under the order-twelve group have now been built from G, and
# their edge counts say the same thing three different ways.  About the
# origin: 18966 points, 94548 edges, which is twelve times G's 7877 exactly.
# About a centre eight units out: 18960 points, 94524 edges, twelve times
# 7877 exactly again.  About the pivot: 13873 points, 73782 edges, 10.64 per
# vertex against G's 9.96 -- the only one of the three with any cross edges
# at all.
#
# The far centre was chosen because the twelve images genuinely overlap there:
# their centres sit 4.01 apart on a circle of radius 7.75 while each copy has
# radius about 3.  They overlap in the plane and share not one edge.
#
# Overlapping is not the condition.  An edge between a point and its rotated
# image needs their distance to be exactly 1, and for a turn of theta about c
# a point at distance rho from c moves 2*rho*sin(theta/2).  At sixty degrees
# that is rho itself, so the closure stitches exactly the points lying at
# distance ONE from the centre, and nothing else.  The pivot has sixty of
# them; the far centre has none; the origin has none.
#
# So a symmetrisation is worth doing only where the graph already has a
# radius-1 ring, and how much it is worth is how big that ring is.  The
# operation does not create structure, it only exploits what the centre
# already sees.
THE_CLOSURE_ONLY_STITCHES_THE_RADIUS_ONE_RING = {
    "the rule": "a turn of theta about c moves a point at distance rho by "
                "2*rho*sin(theta/2); at sixty degrees that is rho, so only "
                "rho = 1 lands a unit away",
    "measured": {
        "about the origin": "94548 = 12 x 7877, zero cross edges",
        "about a far centre 8 out": "94524 = 12 x 7877, zero cross edges, "
                                    "though the twelve copies overlap in the "
                                    "plane",
        "about the pivot": "73782 edges, 10.64/v, and the pivot has 60 points "
                           "of the closure at distance 1",
    },
    "so geometric overlap is not the condition": "exact unit distance is, and "
                                                 "that is decided by the "
                                                 "radius-1 ring at the centre",
    "which makes the choice of centre measurable in advance": "close where "
                                                              "the radius-1 "
                                                              "ring is "
                                                              "biggest",
}


# de Grey's own chain, run one level up, on a carrier that has what it needs.
#
# Gp is G closed under the order-twelve group about its pivot: 13873 points,
# 5-chromatic, symmetric, with twelve rings the field can bite.  Biting it on
# the ring of radius 2 by cos 7/8 -- his Sb angle -- gives 27673 points and
# 30744 cross edges, a real stitch rather than a disjoint union.  Taking the
# new centre to be a point of that bitten ring and biting again at radius 4 by
# cos 31/32 -- his G angle -- gives 55345 points and 314283 edges.
#
# That is his construction, both bites, in his order, on the first carrier in
# this work that is tight and symmetric at once.  It is 5-colourable.
#
# Each of the eleven single bites available on Gp is 5-colourable too, cross
# edges and all: radius 2 adds 30744, radius 4 adds 17712, radius 3 adds
# 23496, and every union colours.
THE_CHAIN_RUNS_AND_NOTHING_HAPPENS = {
    "Gp bitten at radius 2 (his Sb angle)": "27673 points, 157140 edges, "
                                            "30744 cross, 5-colourable",
    "then at radius 4 (his G angle), centre on the first ring":
        "55345 points, 314283 edges, 5-colourable",
    "eleven single bites on Gp": "all stitch, all 5-colourable",
    "why this was expected": "a bite sharpens a disjunction and Gp has no "
                             "capped ring to sharpen -- the exhaustive scan "
                             "found none at any centre or radius",
    "what it rules out": "that the chain itself was the missing ingredient",
}


# The radius-one ring, which every scan here skipped as trivial.
#
# A ring at distance exactly 1 from its centre is capped for free: the centre
# touches all of it, so the ring cannot carry the centre's colour and its
# palette is at most k-1 with no geometry involved.  Every scan skipped it on
# that ground, and the ground is sound for the bound but not for the question.
# A radius-one ring whose palette falls BELOW k-1 is capped by the graph
# rather than by its centre, and that would not be trivial at all -- it is a
# cap on a vertex's own neighbourhood, the one ring every vertex has, and the
# turn that stitches it to itself is the sixty-degree rotation, free in any
# field.
#
# Asked of every vertex, on the whole graph, at both levels:
#
#   Sa at four colours: all 397 neighbourhoods have palette exactly 3
#   G  at five colours: all 1581 neighbourhoods have palette exactly 4
#
# Not one below the free bound, at either level.  So this hole is closed the
# same way at four and at five, which is itself worth knowing: unlike the ring
# caps, which are abundant at four and absent at five, the neighbourhood
# carries nothing at either.  Whatever de Grey's lemma is made of, it is not
# made of neighbourhoods.
THE_NEIGHBOURHOOD_SITS_EXACTLY_AT_THE_FREE_BOUND = {
    "the free bound": "k-1, because the centre is adjacent to all of it",
    "Sa at k=4": "397 of 397 neighbourhoods at palette 3",
    "G at k=5": "1581 of 1581 neighbourhoods at palette 4",
    "below the free bound": 0,
    "why it matters that both levels agree": "the ring caps separate four "
                                             "from five; the neighbourhood "
                                             "does not, so it is not what the "
                                             "cap is made of",
}


# The weaker target, which is what the machine actually consumes -- and it
# fails too.
#
# The lemma, measured, is a palette cap: centre and ring held to two colours
# out of four.  But the cap is not what the bite eats.  The bite needs only
# this: in every colouring, at least one antipodal pair of the ring carries
# one colour twice.  A cap implies it by pigeonhole and is strictly stronger,
# so every scan in this work has been hunting the harder of the two objects.
#
# The weaker statement has a one-call test.  Ask for a colouring in which
# EVERY antipodal pair of the ring is bichromatic; unsatisfiable means some
# pair is always monochromatic, which is the disjunction.
#
# Calibrated on Sa at four colours it returns de Grey's lemma in its operative
# form: centre the origin, D = 4, six ring points in three antipodal pairs,
# and in every 4-colouring one of the three is monochromatic -- with the bite
# cos 7/8, sin sqrt15/8, which is Sb.  It also finds a second disjunction on
# the radius-1 ring, thirty points in fifteen pairs, whose bite is the sixty
# degree rotation; that one is useless precisely because Sa is closed under
# it, which is why he did not use it.
#
# On G at five colours: 150 biteable rings carrying antipodal pairs, 0
# disjunctions, and every one satisfiable within six seconds in total.
#
# So the gap is not that the cap is too strong a thing to ask for at five.
# The weakest statement the construction can use is not there either.
THE_WEAK_DISJUNCTION_FAILS_AT_FIVE_TOO = {
    "what the bite consumes": "in every colouring some antipodal pair of the "
                              "ring is monochromatic -- weaker than a cap, "
                              "which implies it by pigeonhole",
    "the test": "ask for a colouring with every antipodal pair bichromatic; "
                "unsatisfiable is the disjunction",
    "Sa at four": {"centre": "origin", "D": 4, "pairs": 3,
                   "bite": "cos 7/8, sin sqrt15/8 = Sb",
                   "which is": "de Grey's lemma in operative form"},
    "and a second at four": "the radius-1 ring, 30 points in 15 pairs, bite "
                            "the 60 degree rotation -- useless because Sa is "
                            "closed under it",
    "G at five": "150 biteable antipodal rings, 0 disjunctions, all "
                 "satisfiable in six seconds total",
    "so the shortfall is not about strength": "the weakest usable statement "
                                              "is absent as well",
}


# Where to symmetrise, decided by measurement rather than by guess.
#
# The closure under the order-twelve group stitches exactly the radius-1 ring
# at the centre, so the centre worth using is the point of the plane that sees
# the most graph points at distance exactly one.  That point need not be a
# vertex, and finding it needs no search over the plane: a centre with m
# points on its ring is produced by all m(m-1)/2 of their pairs, so counting
# the centres generated by every pair finds the best one in a single pass.
#
# On G, at radius 1 and at radius 2, the answer is the same point --
# (-2.25, 1.9843), which is a vertex.  It sees 24 points of G at distance one
# and 9 at distance two, and the ring-size histogram at radius 1 is
# {24: 2, 10: 24, 9: 72, 8: 48, 7: 120, ...}, so it is one of only two centres
# at the top.
#
# Closing there gives the best carrier built in this work: 11047 points,
# 59919 edges, 10.85 per vertex against Gp's 10.64 and G's 9.96 -- smaller
# and denser than the pivot closure -- with 121 points on its radius-1 ring,
# 72 at D = 1/3, 48 at D = 5/9, 24 at D = 4 and 24 at D = 3.
#
# It is 5-colourable, its five biteable rings are all at full palette, and its
# 195 biteable rings carrying antipodal pairs give no disjunction.
THE_BEST_CENTRE_IS_MEASURABLE_AND_IT_CHANGES_NOTHING = {
    "the rule": "close where the radius-1 ring is biggest; the centre is "
                "found by counting pair-generated centres, not by searching",
    "G's best centre": "(-2.25, 1.9843), a vertex, 24 points at distance 1 "
                       "and 9 at distance 2; top of the histogram with one "
                       "other",
    "the carrier it gives": {"points": 11047, "edges": 59919,
                             "density": "10.85/v vs Gp 10.64 vs G 9.96",
                             "rings": "121 at D=1, 72 at 1/3, 48 at 5/9, "
                                      "24 at 4, 24 at 3"},
    "and it carries nothing": "5-colourable; 5 biteable rings all at full "
                              "palette; 195 antipodal rings, 0 disjunctions",
}


# A search that fails its own calibration, recorded as such.
