THREE_SEARCHES_STOP_AT_THE_SAME_PLACE = """
Evidence, labelled as such, that chi_c(G) is exactly 9/2.

Three methods that share no machinery have now failed in the same spot.

  1. Descent by rescoring.  Seeded from G's K(9/2) map, which scores 4.5003,
     200 moves each flipping an edge of a cycle witnessing the current score
     -- the only edges whose flip can lower it -- and rescoring by binary
     search.  Never below 4.5.
  2. Local repair at a fixed threshold.  Same seed, but the target is fixed
     and the move is: find a cycle violating it, flip one of its edges.  One
     Bellman-Ford pass per move instead of twenty-one.  Asked for 4.4950 --
     five thousandths below the seed -- it was STUCK after 4000 flips.
  3. Four SAT solvers on the circular-clique encoding at 22/5: cadical,
     glucose, maple and minisat, hours each, none returning.

A search that finds nothing has shown nothing, and that holds for all three.
What makes them worth recording together is that they fail differently: one
cannot improve a score, one cannot repair a violation, one cannot close a
proof.  Agreement between methods with different failure modes is worth more
than any of them alone, and it is still not a proof.

The one that surprises is the second.  A threshold five thousandths below
the seed is barely a perturbation, and 4000 repairs could not meet it.  The
orientation landscape around G's optimum is not a shallow basin with a
narrow lip -- it is flat to the search at that resolution.  Which is what
one expects if 9/2 is not a local optimum but the true value.
"""


THE_SPINDLE_NEEDS_A_LARGE_DENOMINATOR = """
Why de Grey's spindle has no direct circular analogue, and exactly where it
does have one.

In the colour setting the device is immediate: a pair forced to share a
colour, plus an edge between them, is a contradiction.  On the circle it is
not.  Suppose u,v are forced to within q of each other in every map -- the
natural analogue of forced-same -- and spindle it, rotating about u so that
v goes to v' with |v - v'| = 1.  Both pairs are forced close, so

        |phi(v) - phi(v')| < 2q,

while adjacency of v and v' only demands at least q.  The two are perfectly
compatible.  The spindle closes nothing.

The arithmetic says what would close it.  If the forcing is to within k
rather than q, the same argument gives |phi(v) - phi(v')| < 2k against a
demand of at least q, so the contradiction appears exactly when

        2k <= q.

At q = 2, the ratio 9/2 this project has been working at, that needs k <= 1:
the pair must be forced to the SAME POSITION, with nothing to spare.  At
q = 9, the ratio 44/9 = 4.8889, it needs only k <= 4 -- forced to within
four of nine positions, which is a far weaker hypothesis about the geometry.

So the spindle mechanism has room in the high-denominator ratios and none at
all in the low ones.  That cuts against the obvious plan.  The instinct is
to attack the nearest rung above G, which is 9/2 because 2 is the smallest
denominator that clears 4 -- and 9/2 is precisely where the one device known
to work in this problem cannot be used.  The rungs near 5, which look
harder because they are stronger statements, are the ones where the
machinery de Grey actually used has somewhere to stand.

Worth testing rather than believing: whether G, or anything built here, has
pairs forced to within 4 at 44/9.  A pair forced that close at a distance
under 2 would be a spindle away from a contradiction, and a contradiction
there is chi_c > 4.8889 -- one ninth short of the whole problem.
"""


CORRECTION_THE_DENOMINATOR_BUYS_NOTHING = """
Correction, within the hour, to the note above.  Its arithmetic is right and
its conclusion is backwards.

That note observed the spindle closes only when 2k <= q, read off k <= 1 at
q = 2 and k <= 4 at q = 9, and concluded the high-denominator ratios give
the mechanism room.  It compared the ABSOLUTE k while the circle was growing
underneath it.

As a fraction of the circle, with r = p/q:

        k/p  <=  (q/2)/p  =  1/(2r)

which is about 1/9 at every ratio near 4.5, whatever the denominator.
Spelt out:

        9/2   k <= 1 of  9   =  1/9      = 0.1111
        19/4  k <= 2 of 19   =  1/9.5    = 0.1053
        24/5  k <= 2 of 24   =  1/12     = 0.0833
        44/9  k <= 4 of 44   =  1/11     = 0.0909

So "forced to within 4 of 44" sounds far milder than "forced to the same or
an adjacent position", and is in fact TIGHTER.  The denominator buys nothing
and the conclusion inverts: 9/2 is, marginally, the friendliest rung for the
spindle rather than the one place it cannot be used.

What survives from the note is the part that was actually new -- the reason
the spindle does not transfer at all.  A forced-close pair plus an edge is
not a contradiction on the circle, because two pairs each forced within q
put their far ends within 2q while adjacency asks only for q.  The device
needs forcing to HALF the adjacency threshold, everywhere, and that is a
strictly stronger hypothesis than the forced-same it replaces.  That is a
real obstruction and it does not depend on the ratio.

Recorded because the error was of the kind this project keeps catching in
its own instruments: a quantity compared without its denominator.  The
five-cycle screen counted quadrilaterals; the growth believed a noisy
estimator; this one read 4 against 1 and forgot 44 against 9.
"""


WHAT_THE_CIRCULAR_FRAME_IS_FOR = """
The synthesis, after both the result and the correction.

chi_c > 5 and chi >= 6 are the same statement, so neither frame can be
harder than the other.  What differs is what each one is good at, and the
work above settles it fairly precisely.

MEASURING is where the circular frame wins, and it wins completely.  The
colour frame answered "5" about a hundred times and ranked nothing.  The
circular frame separates Sa and Y (tight at 4) from the Moser spindle (loose
at 7/2), places G at 4.5 with three independent searches agreeing, reads de
Grey's step as worth about half a colour, tells the instruments that cannot
reach the next rung from those that can, and turns a yes-or-no into a ladder
of provable statements.  None of that was visible before.

CONSTRUCTING is where it does not help, and the reason is now explicit.  De
Grey's two devices both rest on forced-same pairs: the bite produces one,
the spindle converts it into a contradiction.  Neither survives the
translation.  A forced-same pair becomes "forced within q", which is not a
contradiction with an edge, and making the spindle close requires forcing to
q/2 -- half the adjacency threshold, at every ratio, as the correction
above establishes.  That is strictly stronger than what the colour frame
asks for, so a construction is better built where the mechanisms live.

The practical division: build in colours, measure in circles.  Every
candidate this project produced was built by colour-frame reasoning and then
weighed on the circular scale, which is exactly the right way round, and it
is how the density route was closed with a number instead of an opinion.

It also says what would change the picture.  Not a cleverer spindle -- the
q/2 obstruction is unconditional -- but a device that produces forced-CLOSE
pairs directly, with slack, rather than forced-same pairs that then have to
be converted.  Nothing here produces one, and the arc bound built to look
for them returned nothing on the neighbourhoods it was pointed at.  That is
the open end, stated as precisely as this pass can state it.
"""


THE_BITE_IMPOSES_A_FLOOR_ON_THE_ARC_NOT_A_CEILING = """
De Grey's exhaustion redone in positions, and the answer is the wrong way up.

His lemma came from forcing the centre and its radius-2 hexagon to each of
the 187 colour partitions and finding ten survivors: at most TWO colours on
the seven points, centre never alone.  A cap.  The same exhaustion in
positions is small enough to do completely -- seven points, nine positions,
9^7 = 4782969 assignments, all of them checked.

At K(9/2):

    ring alone (hexagon)          424764 survive   arc span 2 to 7
    ring + bite (centre joined)    14922 survive   arc span 4 to 7

The bite cuts the survivors by a factor of 320, which is real work.  But
look at what it does to the span: the minimum rises from 2 to 4.  It imposes
a FLOOR, not a ceiling.  The seven points are forced to spread over at least
four of the nine positions, where the colour lemma forced them to gather
into at most two classes.

The rest follows the same way.  Distinct positions used runs 3 to 7, so
there is no cap there either.  And the antipodal ring pairs, which in
colours come back forced-same, here have their widest member anywhere from 0
to 4 -- no forcing at all.

That is the spindle's q/2 requirement failing at its source: the device that
produces the forced pair in colours produces a spread in positions.

One caveat which is the whole of the next experiment.  This exhausts the
gadget ALONE, and de Grey's lemma is not about the gadget alone -- seven
points on their own are not capped at two colours either, since a hexagon
with a centre joined to it 3-colours perfectly well.  His cap comes from the
gadget sitting inside Sa, with the carrier doing the work.  So the honest
statement is: the bite in isolation gives a floor rather than a ceiling in
positions, and whether the carrier reverses that is a separate question,
asked of the carrier.
"""


DE_GREYS_LEMMA_HAS_NO_POSITIONAL_ANALOGUE = """
The device, looked for in the right place, three ways, and it is not there.

De Grey's lemma: the centre and its radius-2 ring take at most TWO of four
colours, and the centre is never alone.  That cap is the whole engine -- it
is what the bite sharpens into a forced pair and the spindle turns into a
contradiction.  If the circular frame has an analogue, this is where it
lives.

    1.  The gadget alone, exhausted completely.  Seven points, nine
        positions, all 4782969 assignments.  The hexagon alone leaves 424764
        survivors spanning arcs of 2 to 7; adding the bite leaves 14922 --
        a factor of 320 -- spanning 4 to 7.  The bite raises the MINIMUM
        span from 2 to 4.  A floor, where the colour version gives a
        ceiling.

    2.  The gadget inside the carrier, bounded exactly.  The centre of G and
        the twelve points at distance 2 from it, over ALL homomorphisms of
        the whole 1581-point graph to K(9/2), by bisection on the width:

            arc bound = 9 of 9.

        They can occupy the entire circle.  Not a weak cap, not a cap that
        needs a bigger carrier -- no cap.

    3.  Forced-close pairs, searched for directly.  A spindle needs two
        points forced to within q/2 = 1.  Of the 200 nearest non-adjacent
        pairs in Sa, not one is forced, each ruled out by its own UNSAT.

So the colour lemma says "at most 2 of 4" and the position measurement says
"all 9 of 9".  The translation does not weaken the lemma; it INVERTS it.

The mechanism is visible now, and it is not an accident of this
configuration.  In colours, "few colours" is a restriction and adjacency
only forbids equality, so a tightly linked set can be gathered.  In
positions, adjacency demands SEPARATION -- at least q round the circle --
so the very links that gather colours push positions apart.  A hexagon of
consecutive unit pairs is the extreme case: six mutually chained points each
forced q from the next.  The geometry that made the cap is the geometry that
forbids the arc.

That is the end of the line for lifting de Grey's device, and it is the
reason the earlier note's "build in colours, measure in circles" is not a
preference but a constraint.
"""


SEARCHING_THE_SPACE_OF_LEMMAS_INSTEAD_OF_THE_SPACE_OF_GRAPHS = """
Every search in this project grows a graph from a seed.  De Grey did not.
He found a seven-point configuration whose palette is capped -- the centre
and its radius-2 ring take at most two of four colours -- and the whole
construction is that lemma plus a way to make copies conflict.  He found it
by insight.  Nobody has enumerated small configurations and asked each one
for its cap, which is a search over LEMMAS rather than over graphs, and it
turns out to be cheap: "does any proper k-colouring spread all k colours
across S" is one solver call, and UNSAT is a cap.

Two things had to be fixed before any of it meant anything.

The trivial caps.  A set with a common neighbour outside it is capped for
free -- if w is adjacent to every point of S then w needs a colour none of
them has.  A neighbourhood is the standard case, w being the centre.  The
first version reported every unit ring in G as a discovery, dozens of them,
and they are the definition of a proper colouring rather than a lemma.
Filtered now.

The cap VALUE.  "Capped below k" is nearly worthless; de Grey's cap is 2 of
4, and a cap of 4 of 5 constrains almost nothing.  The palette is now
measured by bisection, so the strength of each lemma is reported.

THE CONTROL, which decides whether the silence elsewhere means anything.
Run on Sa at four colours over 1200 configurations drawn from 39566:

    CAP 2 of 4  |S|=6  ring r2=4.000 about vertex 0
    CAP 2 of 4  |S|=7  centre + that ring
    CAP 3 of 4  |S|=6  ring r2=1.708 about vertex 1

The first two are de Grey's lemma, with his configuration and his exact
value, found unaided among thirty-nine thousand candidates.  The third is
one his account does not mention -- weaker at 3 of 4, and real.

THE QUESTION.  The same search on G at five colours: 157570 candidate
configurations, and over the first 15000 tested, ZERO caps.

That converts the project's earlier reading -- the cap is abundant at four
and absent at five -- from an absence into an absence with a witness.  The
instrument demonstrably finds caps where they exist, reports their strength,
and refuses the trivial ones.  Its silence at five colours is evidence about
the carrier rather than about the search.
"""


THE_CAP_REQUIRES_TIGHTNESS_AND_THAT_JOINS_THE_TWO_MEASUREMENTS = """
The two main measurements of this pass turn out to be the same measurement.

    the palette cap is abundant at four colours and absent at five
    Sa and Y are tight at four (chi_c = 4 exactly); G is NOT tight at five
    (chi_c(G) = 4.5)

Those were found independently, by different instruments, on different
questions.  They say the same thing.  A cap asserts that no proper colouring
spreads k colours across a set -- the colouring has no room.  Tightness
asserts that no ratio below k admits a homomorphism -- the colouring has no
room.  The cap is the local statement and chi_c = k is the global one.

So the caps live exactly where the carrier is tight, and their absence at
five is not a failure of imagination about shapes.  It is the slack: G
reaches five in the integer sense while sitting half a colour below it on
the real scale, and half a colour of slack is enough for every configuration
tried -- 20000 of them in G, with an instrument that rediscovers de Grey's
own lemma at four with its exact value of 2 of 4 -- to spread all five
colours somewhere.

That reorders the programme.  The prerequisite for de Grey's engine one
level up is not a cleverer gadget.  It is a CARRIER TIGHT AT FIVE.  Give the
search a unit-distance graph with chi_c = 5 and the caps should appear in it
the way they appear in Sa; without one, no shape will be capped, because
there is room for every shape.

One caveat that keeps the claim honest.  The link is stated for the colour
frame only.  G IS tight at 4.5 on the circular scale, and the circular
analogue of the cap -- the arc bound of its centre and ring -- is 9 of 9,
no cap at all.  So tightness at a ratio does not produce a positional cap,
which is the same inversion recorded earlier: adjacency demands separation
on the circle and only forbids equality in colours.  Tightness buys caps in
colours and nothing in positions.
"""


