THE_UPPER_BOUND_NEEDS_TILES_NOT_CELLS = """
The direction nobody has pushed, attempted, and the tool is wrong for a
reason worth stating.

The whole pass attacks the lower bound.  The UPPER bound has not moved since
Isbell in 1950 -- seven colours by a hexagonal tiling -- and no six-colouring
of the plane has ever been built.  Density does not forbid one: a colour
class is a set avoiding distance 1, the densest known has density about
0.229, and five classes covering the plane need only 0.2 each.  What is
missing is an arrangement, not room.

So: a torus, discretised into cells, with a CONSERVATIVE edge whenever some
point of one cell is exactly a unit from some point of another.  A proper
colouring of the cells would then be a genuine periodic colouring of the
plane, and unsatisfiability would say nothing, since the conservative edges
constrain more than the plane does.  The control is Isbell: seven colours
must come out satisfiable or the model is useless.

At 3 x 3 with 22 x 22 cells of side 0.136: 484 cells, 29040 edges, MEAN
DEGREE 120.  Seven colours does not return.  The model cannot reproduce a
tiling that has existed for seventy-five years.

The reason is not coarseness and no refinement fixes it.  Avoiding distance
1 is a measure-zero condition; a cell of diameter delta turns it into a band
of width about 2*delta around the unit circle, so the discretised graph
forbids an annulus where the plane forbids a curve.  Shrinking delta shrinks
the band and explodes the cell count at the same rate, and the band never
becomes the curve.

What the upper bound needs is TILES, not cells: regions whose diameter is
below 1 and whose same-coloured copies are separated by more than 1, which
is exactly how the hexagonal colouring works and why it is checkable by hand.
That is a different kind of search -- over shapes and lattices, with exact
geometry -- and it is a project rather than an experiment.  Recorded so the
next attempt does not start by discretising.
"""


THE_BRICK_EXISTS_AT_FOUR_AND_THE_ZERO_AT_FIVE_IS_A_SAMPLE = """
The atom of any 6-chromatic graph, searched for, found at four colours and
absent at five -- with a correction to how the absence was reported.

A 6-critical graph has a vertex whose five neighbours take five different
colours in every proper 5-colouring.  Those five lie on a unit circle, where
two points are adjacent only if they subtend 60 degrees, so the circle
carries a subgraph of disjoint hexagons: bipartite, maximum clique 2.  At
most TWO of the five can be adjacent, so the rest must be NON-ADJACENT PAIRS
FORCED TO DIFFER, which the carrier has to supply.  That pair is the brick,
and finding one is a single solve.

    Sa        4 colours   29 forced non-adjacent pairs   the brick exists
    Y         4 colours    0 in this sample
    24-core   4 colours    0 of its 220 pairs
    denseSa   4 colours    0 in this sample
    G         5 colours    0 in a sample of 25000 pairs

Sa's pairs are all at distance exactly 1/3 -- and Y is the union LESS the
points at (+-1/3, 0), which is de Grey's own pruning.  Removing those points
removes the forcing, which is the same fact the earlier note recorded as
"the pruning costs two thirds", arriving from a different direction.

The correction.  Forced-different is MONOTONE in the carrier: every colouring
of a supergraph restricts to the subgraph, so a pair forced in Sa is forced
in anything containing Sa.  denseSa contains Sa and the scan reported 0 for
it against Sa's 29, which is impossible.  The scan samples 400 source
vertices out of 3501 and missed them.  So the verdict it printed -- "no
brick, no 6-chromatic graph can live in this carrier" -- overclaimed, and
the honest reading of every zero here is NOT FOUND IN THIS SAMPLE.

That applies to G at five as well.  Twenty-five thousand pairs and none
forced is evidence and not exhaustion, and it agrees with the 400
neighbourhoods scanned earlier and with the 22 per cent of G's vertices that
have a spare colour.  But it is not the theorem the wording claimed.
"""


THE_SEED_EXPERIMENT_TESTED_THE_WRONG_THING = """
The one stone left unturned, turned, and it was the wrong stone -- with the
control saying so unambiguously.

The concern was real.  Every carrier measured in this project descends from
de Grey's points in one field, so "75500 configurations across two carriers"
is one point of the space seen from several angles.  Whether the absence of
forcing at five colours is a fact about FIVE or a fact about THIS SEED had
never been tested.

So: close a small seed under circle intersection in several fields and look
for forced pairs.  Q(sqrt2), Q(sqrt3), Q(sqrt2,sqrt3), and then four-
generator fields at de Grey's own richness with the generators swapped --
(3,5,7,11), (2,3,5,7), (3,5,7,13), (2,3,5,7,11).

    Q(sqrt3)            18 points
    Q(sqrt2)             7 points
    Q(sqrt2,sqrt3)      65 points
    de Grey's own field 19 points     <- the control, and the verdict
    swap 11 for 2       79 points
    swap 11 for 13      19 points
    five generators     79 points

Nineteen points in de Grey's own field, where his Sa has 397.  The
experiment does not test the hypothesis: a naive closure from four points is
small in EVERY field, so the zeros say nothing about seeds.

What it does establish is why the field matters at all.  Two unit circles
about points at squared distance D meet at
midpoint +- (1/2)sqrt((4-D)/D)*(-dy,dx), so the meeting points exist in the
field only when (4-D)/D is a SQUARE there.  With one or two generators that
almost never happens and the closure dies in its first round.  The
literature's rich fields are a condition of existence, not a convention.

And the real lesson is about Sa.  It is not a closure at all -- it is a
designed assembly: hexagons at radius 2, rotations through chosen angles,
and a deliberate pruning of the points at (+-1/3, 0), which is exactly where
its 29 forced pairs live.  Testing another seed properly means reproducing a
construction of that scale in another field, which is a project rather than
an afternoon, and the zeros above are not evidence against it.
"""
